  var savedData = {};
  var keys = Object.keys(this.localStorage);
  keys.forEach(function (k) { savedData[k] = this.localStorage.getItem(k); }, this);
  this.disposeApp();
  this.loadApp();
  keys.forEach(function (k) { this.localStorage.setItem(k, savedData[k]); }, this);
  // Re-run app init to read from restored localStorage
  var appPath = require('path').join(__dirname, '..', '..', 'js', 'app.js');
